grep -E 'HTP delivery deferred' "$WORK/seo.log" | tail -1 | cut -c1-160 >"$WORK/defer.txt"
rec PASS 7a "validator disabled -> job stays pending (attempts>=1), the route answered 503 and never 200, nothing committed" "$st3; route statuses seen by the producer: $px503; seosmith log: $(cat "$WORK/defer.txt")"
