[[ "$(tail -1 <<<"$W")" == 200 && "$(head -n -1 <<<"$W" | jq -r .status)" == in_progress && "$(head -n -1 <<<"$W" | jq -r '.finding_key[0:16]')" == "$nfk" ]] && rec PASS 8d "remediation_save on a schema-4 fixture finding (POST /work; status in_progress, finding_key = findings[0].key)" "$(head -n -1 <<<"$W" | jq -c '{status,finding_key:(.finding_key[0:16])}')" || rec FAIL 8d "remediation_save on a schema-4 finding" "$W"
WL="$(curl -s -w '\n%{http_code}' "$API/websites/$NEG/seo/audits/$rid/work?finding_index=0" -H "authorization: Bearer $(jwt cap)")"
[[ "$(tail -1 <<<"$WL")" == 200 ]] && head -n -1 <<<"$WL" | jq -e 'type=="array" and length>=1 and any(.[]; .status=="in_progress")' >/dev/null \
  && rec PASS 8c "remediation_list returns the saved work item" "$(head -n -1 <<<"$WL" | jq -c '[.[]|{status}]')" || rec FAIL 8c "remediation_list returns the saved work item" "$WL"
# Mutated report. `deliver_once` (SEOsmith's example) generates a RANDOM delivery id, so the route's delivery-id binding
# rejects even an unmutated report; its 422 therefore proves nothing about the mutation (review M2, step 9). The proof is the
# id-correct send of the mutated report (the id equals request.request_id): it must be 422 semantic_mismatch at stage summary,
# with no row, while the unmutated twin of the same content is accepted (8b above). deliver_once runs once on each report as an INFO control.
mut="$(HTP_INGEST_TOKEN="${SITE_TOKEN[cap]}" "$DELIVER" "$INGEST" "$WORK/neg-mut.json" 2>&1 | tail -1)"
node "$here/prep.mjs" "$S4FIX/complete-missing-h1.json" "$WORK/neg-ok2.json" --request "$(uuid)" --ts 2026-11-20T12:00:00Z
mutctl="$(HTP_INGEST_TOKEN="${SITE_TOKEN[cap]}" "$DELIVER" "$INGEST" "$WORK/neg-ok2.json" 2>&1 | tail -1)"
rec INFO 9c "deliver_once control (random delivery id)" "mutated: '$mut'; UNmutated: '$mutctl' (equal results show deliver_once cannot discriminate the mutation)"
mut2="$(node "$here/send.mjs" "$INGEST" "${SITE_TOKEN[cap]}" "$WORK/neg-mut.json")"
mutrid="$(jq -r .request.request_id "$WORK/neg-mut.json")"; mutrows="$(q "select count(*) from public.seosmith_audits where delivery_id='$mutrid'")"
[[ "$(jq -r .status <<<"$mut2")" == 422 && "$(jq -r '.body|fromjson|.error' <<<"$mut2")" == semantic_mismatch && "$(jq -r '.body|fromjson|.stage' <<<"$mut2")" == summary && "$mutrows" == 0 ]] \
  && rec PASS 9 "mutated report (id-correct send) refused 422 semantic_mismatch at stage summary; no row stored" "$(jq -c '{status,body}' <<<"$mut2" | cut -c1-200); rows=$mutrows" || rec FAIL 9 "mutated report refused 422 semantic_mismatch/summary" "send=$mut2 rows=$mutrows"
# legacy 1/2 on the OLD route
lid="$(uuid)"; node "$here/prep.mjs" "$FIX/v2-complete.json" "$WORK/v2.json" --request "$lid" --ts 2026-11-19T10:00:00Z
l2="$(node "$here/send.mjs" "$LEGACY" "${SITE_TOKEN[cap]}" "$WORK/v2.json")"
[[ "$(jq -r .status <<<"$l2")" == 200 ]] || rec FAIL 10 "legacy schema 2 accepted" "$l2"
lid1="$(uuid)"; node "$here/prep.mjs" "$FIX/legacy.json" "$WORK/v1.json" --request "$lid1" --ts 2026-11-19T09:00:00Z
l1="$(node "$here/send.mjs" "$LEGACY" "${SITE_TOKEN[cap]}" "$WORK/v1.json")"
[[ "$(jq -r .status <<<"$l1")" == 200 ]] || rec FAIL 10 "legacy schema 1 accepted" "$l1"
for pair in "$lid:v2" "$lid1:v1"; do
  id="${pair%%:*}"; D="$(get cap "/websites/$NEG/seo/audits/$id")"; dcode="$(tail -1 <<<"$D")"; head -n -1 <<<"$D" >"$WORK/legacy-detail.json"
  jq -j .report_json "$WORK/legacy-detail.json" >"$WORK/legacy-detail.report"; src="$WORK/${pair##*:}.json"
  cmp -s "$WORK/legacy-detail.report" "$src" && [[ "$dcode" == 200 ]] || rec FAIL 10 "legacy ${pair##*:} read path unchanged" "detail http $dcode, report_json differs"
done
src2="$(q "select ingestion_source||':'||(report->>'schema_version') from public.seosmith_audits where delivery_id='$lid'")"; src1="$(q "select ingestion_source||':'||(report->>'schema_version') from public.seosmith_audits where delivery_id='$lid1'")"
ix2="$(q "select state from public.seosmith_lifecycle_indexed where delivery_id='$lid'")"; ix1="$(q "select state from public.seosmith_lifecycle_indexed where delivery_id='$lid1'")"
[[ "$src2" == worker:2 && "$src1" == *:1 && "$ix2" == indexed_v1 && "$ix1" == legacy ]] || rec FAIL 10 "legacy rows stored as expected" "v2 row=$src2 (want worker:2) v1 row=$src1 (want *:1) indexed v2=$ix2 (want indexed_v1) v1=$ix1 (want legacy)"
rec PASS 10 "legacy schema 1/2 via /integrations/seosmith/audits" "v2: $(jq -c '{status,ms}' <<<"$l2"), v1: $(jq -c '{status,ms}' <<<"$l1")); detail report_json byte-identical for both; indexed state v2=$(q "select state from public.seosmith_lifecycle_indexed where delivery_id='$lid'") v1=$(q "select state from public.seosmith_lifecycle_indexed where delivery_id='$lid1'")"
# the 15-key capability read on the legacy route still lists all three versions
capj="$(curl -s "$API/integrations/seosmith/capabilities")"
jq -e '.schema_versions==[1,2,4] and .max_report_bytes==4952756 and .exact_bytes==true and .receiver=="htp" and .policy_wire_contracts==["s14-wire-1"]' <<<"$capj" >/dev/null \
  && rec PASS 10b "capabilities: schema_versions [1,2,4], max_report_bytes 4952756, exact_bytes, receiver htp, wire s14-wire-1" "$(jq -c . <<<"$capj")" || rec FAIL 10b "capabilities" "$capj"

