echo "== step 11: mixed generation on the SAME binding and generation (schema 2, then 4, 4; bump; 4, 4), real crawls"
MIX="${SITE_ID[mix]}"
start_serve() { # start_serve <name> <port> <wire|v2> <ingest-url>
  local n="$1" port="$2" mode="$3" url="$4" extra=()
  if [[ "$mode" == wire ]]; then extra=(SEOSMITH_POLICY_WIRE_V1=true "SEOSMITH_ADVISORY_POLICY=$seo/fixtures/policies/production-default.json"); else extra=(SEOSMITH_EVIDENCE_CONTRACT_V2=true); fi
  env SEOSMITH_DB="$WORK/$n.sqlite" SEOSMITH_BIND="127.0.0.1:$port" SEOSMITH_API_TOKEN="$SEO_API_TOKEN" HTP_INGEST_URL="$url" HTP_INGEST_TOKEN="${SITE_TOKEN[mix]}" "${extra[@]}" RUST_LOG=info "$SEOBIN" serve >"$WORK/$n.log" 2>&1 &
  pids+=($!); wait_for 30 curl -sf "http://127.0.0.1:$port/health/ready" || rec FAIL 11 "serve $n up" "$(tail -3 "$WORK/$n.log")"; }
crawl_to() { # crawl_to <base> <gen> -> request id once delivered
  local id; id="$(uuid)"; SU="$1"; local r; r="$(submit "$id" "$MIX" "$2" https://www.kerryhatcher.com/ 3 10)"; [[ "$(tail -1 <<<"$r")" == 202 ]] || { echo "submit failed $r" >&2; echo FAILSEND; return; }
  wait_state "$id" '.delivery_state=="delivered"' 240 >/dev/null || { echo FAILSEND; return; }; echo "$id"; }
processjob() { # processjob -> "<delivery> <state:hold>" for the next claimable job, or noclaim
  local c l d; c="$(q "set role service_role; select public.audit_event_claim()" 2>&1 | tail -1)"; l="$(jq -r '.lease_token // .lease // empty' <<<"$c" 2>/dev/null)"; d="$(jq -r '.delivery_id // empty' <<<"$c" 2>/dev/null)"
  [[ -n "$l" && -n "$d" ]] || { echo "noclaim"; return; }
  psql_ >/dev/null <<SQL
set role service_role;
begin;
select public.audit_event_snapshot_lock();
select public.audit_event_process('$d','$l'::uuid);
commit;
SQL
  echo "$d $(q "select state||coalesce(':'||hold_reason,'') from public.audit_event_jobs where delivery_id='$d'")"; }
drain() { local o; for _ in $(seq 1 12); do o="$(processjob)"; [[ "$o" == noclaim ]] && break; echo "  job: $o"; done; }
# State surgery, stated openly: every OTHER site's still-pending event jobs are marked processed so that this step's
# drain sees only its own site. It hides those jobs from the queue for the rest of the run.
q "update public.audit_event_jobs set state='processed' where website_id<>'$MIX' and state='pending'" >/dev/null
jstate() { q "select state||coalesce(':'||hold_reason,'') from public.audit_event_jobs where delivery_id='$1'"; }
# The processor runs after EACH delivery, as it would in production (a receipt processed after a later one exists is late_or_tied).
start_serve mixv2 8918 v2 "$LEGACY"; start_serve mixw 8919 wire "$INGEST"
G="$(q "select generation from public.seosmith_bindings where website_id='$MIX'")"
m2="$(crawl_to http://127.0.0.1:8918 "$G")"; [[ "$m2" != FAILSEND ]] || rec FAIL 11 "mixed: schema-2 crawl delivered" "$(tail -3 "$WORK/mixv2.log")"; drain
m4a="$(crawl_to http://127.0.0.1:8919 "$G")"; [[ "$m4a" != FAILSEND ]] || rec FAIL 11 "mixed: schema-4 crawl a" "$(tail -3 "$WORK/mixw.log")"; drain
m4b="$(crawl_to http://127.0.0.1:8919 "$G")"; [[ "$m4b" != FAILSEND ]] || rec FAIL 11 "mixed: schema-4 crawl b" "$(tail -3 "$WORK/mixw.log")"; drain
SU="$SEOURL"
gens="$(q "select string_agg(report->>'schema_version'||'@g'||generation||'/'||ingestion_source,' , ' order by scan_at) from public.seosmith_audits where website_id='$MIX'")"
drain
rec INFO 11a "mixed generation G=$G audits (scan order)" "$gens; jobs: schema2=$(jstate "$m2") schema4(first)=$(jstate "$m4a") schema4(second)=$(jstate "$m4b")"
[[ "$(jstate "$m4b")" == held:history_unknown ]] && rec PASS 11b "processor raises history_unknown for the schema-4 job in a mixed 2/4 generation" "second schema-4 job: $(jstate "$m4b"); first schema-4: $(jstate "$m4a"); schema-2: $(jstate "$m2")" || rec FAIL 11b "history_unknown for a schema-4 job in a mixed generation" "second schema-4 job: $(jstate "$m4b"); first: $(jstate "$m4a"); schema-2: $(jstate "$m2")"
q "update public.seosmith_bindings set generation=generation+1 where website_id='$MIX'" >/dev/null
G2="$(q "select generation from public.seosmith_bindings where website_id='$MIX'")"
n4a="$(crawl_to http://127.0.0.1:8919 "$G2")"; drain; n4b="$(crawl_to http://127.0.0.1:8919 "$G2")"; drain; SU="$SEOURL"
[[ "$n4a" != FAILSEND && "$n4b" != FAILSEND ]] || rec FAIL 11 "post-bump crawls" "failed: $(tail -3 "$WORK/mixw.log")"
# Reading of the plan's "assert one event" (written down here and in the report): one JOB per receipt, and the receipt's EVENTS are exactly
# the pass->fail transitions between the two post-bump receipts. For an unchanged site that is 0 events; the assertion computes the expected
# number from the lifecycle table instead of assuming it.
ev="$(q "select count(*) from public.audit_events where website_id='$MIX' and generation=$G2 and delivery_id='$n4b'")"
exp_ev="$(q "select count(*) from public.seosmith_lifecycle_evaluations b join public.seosmith_lifecycle_evaluations a on a.entity_id=b.entity_id and a.rule=b.rule where b.delivery_id='$n4b' and a.delivery_id='$n4a' and b.evaluation->>'outcome'='fail' and a.evaluation->>'outcome'='pass'")"
jobs2="$(q "select count(*) from public.audit_event_jobs where website_id='$MIX' and generation=$G2")"; oldheld="$(q "select count(*) from public.audit_event_jobs where website_id='$MIX' and generation=$G and state='held' and hold_reason='history_unknown'")"
[[ "$(jstate "$n4b")" == processed && "$ev" == "$exp_ev" && "$jobs2" == 2 && "$oldheld" == 3 ]] && rec PASS 11c "after the generation bump (G=$G -> $G2) the schema-4 pair processes: 2 jobs, second processed, events == lifecycle pass->fail diff; old generation's 3 jobs stay held history_unknown" "first=$(jstate "$n4a") second=$(jstate "$n4b"); events for the second receipt=$ev expected(pass->fail)=$exp_ev; jobs in gen $G2=$jobs2; held old-gen jobs=$oldheld" || rec FAIL 11c "post-bump processing" "first=$(jstate "$n4a") second=$(jstate "$n4b") events=$ev expected=$exp_ev jobs=$jobs2 oldheld=$oldheld"
D="$(get mix "/websites/$MIX/seo/audits?limit=10")"; lv="$(head -n -1 <<<"$D" | jq -c '[.items[] | (.summary.schema_version)]')"
[[ "$(tail -1 <<<"$D")" == 200 && "$lv" == "[4,4,4,4,2]" ]] && rec PASS 11d "audit list read path on a mixed-generation website returns [4,4,4,4,2] (newest first)" "$lv" || rec FAIL 11d "audit list on a mixed-generation website (want [4,4,4,4,2])" "$lv http $(tail -1 <<<"$D")"

# ---------------------------------------------------------------------------------------------------
echo "== M5: processor ordering (late_or_tied) when receipts are processed in a batch instead of one by one"
# audit_event_process holds a receipt `late_or_tied` as soon as a LATER audit of the same site/fqdn/generation exists (migration 20261203000000:129).
# The steps above drain after every delivery. Here three receipts arrive first and ONE drain pass follows (a batching/cron processor).
b1="$(crawl_to http://127.0.0.1:8919 "$G2")"; b2="$(crawl_to http://127.0.0.1:8919 "$G2")"; b3="$(crawl_to http://127.0.0.1:8919 "$G2")"; SU="$SEOURL"
[[ "$b1" != FAILSEND && "$b2" != FAILSEND && "$b3" != FAILSEND ]] || rec FAIL 16 "batch crawls delivered" "$(tail -3 "$WORK/mixw.log")"
before="$(for d in $b1 $b2 $b3; do jstate "$d"; done | tr '\n' ' ')"
drain
sb1="$(jstate "$b1")"; sb2="$(jstate "$b2")"; sb3="$(jstate "$b3")"
[[ "$before" == "pending pending pending " && "$sb1" == held:late_or_tied && "$sb2" == held:late_or_tied && "$sb3" == processed ]] \
  && rec PASS 16 "batch drain: the two older receipts are held late_or_tied, only the newest is processed (production cadence must be per receipt)" "before=$before; after: older=$sb1, middle=$sb2, newest=$sb3" \
  || rec FAIL 16 "batch drain ordering" "before=$before after: $sb1 / $sb2 / $sb3"
fns="$(q "select string_agg(proname, ',' order by proname) from pg_proc where pronamespace='public'::regnamespace and proname like 'audit_event%'")"
callers="$(grep -rIl -e audit_event_claim -e audit_event_process "$root" --exclude-dir=node_modules --exclude-dir=target --exclude-dir=.git | sed "s#$root/##" | sort | tr '\n' ' ')"
rec INFO 16b "no recovery path for a held job, and no production caller of the processor in this repository" "audit_event_* functions: $fns (claim/hold/process/snapshot_lock/history; none requeues a held job); files that call audit_event_claim/process: $callers; processing_enabled defaults to false"

# ---------------------------------------------------------------------------------------------------
echo "== web display read path: owner API detail + MCP website_audit_detail on a schema-4 row"
mres="$(node "$here/mcp.mjs" "$API" "$(jwt kh)" "$KH" "$R1" "$WORK/r1.json" 2>&1)"; mrc=$?
[[ $mrc == 0 ]] && rec PASS 12m "MCP detail/export on a real schema-4 audit" "$mres" || rec FAIL 12m "MCP detail/export on a real schema-4 audit" "$mres"
mres2="$(node "$here/mcp.mjs" "$API" "$(jwt cap)" "${SITE_ID[cap]}" "$rid" "$WORK/neg-ok.json" 2>&1)"; mrc=$?
[[ $mrc == 0 ]] && rec PASS 12n "MCP detail/export on the schema-4 fixture audit" "$mres2" || rec FAIL 12n "MCP detail/export on the schema-4 fixture audit" "$mres2"

# ---------------------------------------------------------------------------------------------------
echo "== host quietness (timing)"
quiet() { local l; l="$(cut -d' ' -f1 /proc/loadavg)"; (( $(echo "$l < ${QUIET_MAX:-2.5}" | bc -l) )); }
for _ in $(seq 1 ${QUIET_WAIT_STEPS:-60}); do quiet && break; sleep 10; done
IDLE="$(vmstat 1 3 | tail -1 | awk '{print $15}')"; LOADT="$(cut -d' ' -f1-3 /proc/loadavg)"; rec INFO 13q "host load before timing (the 1-minute load average gates, polled every 10 s for up to ${QUIET_WAIT_STEPS:-60} polls = 10 min; 5/15-min averages are shown)" "loadavg $LOADT, cpu idle ${IDLE}% ($(nproc) cpus; others running: $(ps -eo pcpu,comm --sort=-pcpu | head -4 | tail -3 | tr '\n' ';' | tr -s ' '))"
quiet || rec INFO 13q "host NOT quiet" "timing numbers below carry a contention caveat (loadavg $LOADT)"

echo "== step 12: S2 exact-cap fixture, commit path through the API (256 MB scope)"
[[ "$(stat -c %s "$CAPF")" == "$CAP_BYTES" ]] || rec FAIL 12 "exact-cap fixture size" "$(stat -c %s "$CAPF")"
pid="$(apipid)"; rss0="$(grep VmHWM /proc/$pid/status | awk '{print $2}')"
: >"$WORK/cap.times"
for i in $(seq 1 "$CAP_RUNS"); do
  id="$(uuid)"; node "$here/prep.mjs" "$CAPF" "$WORK/cap-$i.json" --request "$id"
  [[ "$(stat -c %s "$WORK/cap-$i.json")" == "$CAP_BYTES" ]] || rec FAIL 12 "exact-cap stays exact after id rewrite" "$(stat -c %s "$WORK/cap-$i.json")"
  r="$(node "$here/send.mjs" "$INGEST" "${SITE_TOKEN[cap]}" "$WORK/cap-$i.json")"
  st="$(jq -r .status <<<"$r")"; [[ "$st" == 200 ]] || { echo "$r"; tail -5 "$WORK/api.log"; rec FAIL 12 "exact-cap run $i admitted" "$r"; }
  recv_ms="$(q "select (extract(epoch from received_at)*1000)::bigint from public.seosmith_audits where delivery_id='$id'")"
  endms="$(jq -r .end_epoch_ms <<<"$r")"
  echo "$(jq -r .ms <<<"$r") $((endms - recv_ms))" >>"$WORK/cap.times"
  rm -f "$WORK/cap-$i.json"
done
rss1="$(grep VmHWM /proc/$pid/status | awk '{print $2}')"; peak="$(cat "$(apicg)/memory.peak" 2>/dev/null || echo 0)"; oom="$(grep -E '^oom_kill ' "$(apicg)/memory.events" 2>/dev/null | cut -d' ' -f2)"
(( peak > 0 )) && [[ -n "$oom" ]] || rec FAIL 12c "cgroup memory files readable" "peak='$peak' oom='$oom' at $(apicg)"
pstat() { sort -n | awk -v p="$1" '{a[NR]=$1} END{i=int(NR*p+0.999999); if(i<1)i=1; if(i>NR)i=NR; print a[i]}'; }
rt50="$(cut -d' ' -f1 "$WORK/cap.times" | pstat 0.5)"; rt99="$(cut -d' ' -f1 "$WORK/cap.times" | pstat 0.99)"; rtmax="$(cut -d' ' -f1 "$WORK/cap.times" | sort -n | tail -1)"
cm50="$(cut -d' ' -f2 "$WORK/cap.times" | pstat 0.5)"; cm99="$(cut -d' ' -f2 "$WORK/cap.times" | pstat 0.99)"; cmmax="$(cut -d' ' -f2 "$WORK/cap.times" | sort -n | tail -1)"
margin=$(( 25000 - rtmax ))
rec INFO 12a "exact-cap API round trip ($CAP_RUNS runs, ms)" "p50=$rt50 p99=$rt99 max=$rtmax; in-DB estimate (client response end - received_at, which is the time inside the commit transaction, so it EXCLUDES body read and admit) p50=$cm50 p99=$cm99 max=$cmmax; p99 = max at n=$CAP_RUNS; margin to 25 s = ${margin} ms; loadavg $(cut -d' ' -f1-3 /proc/loadavg)"
(( rtmax < 25000 )) && rec PASS 12b "round trip inside 25 s" "max ${rtmax} ms, margin ${margin} ms; p99 ${rt99} ms" || rec FAIL 12b "round trip inside 25 s" "max ${rtmax} ms"
rec INFO 12c "API peak memory on the 256 MB scope" "VmHWM $((rss1/1024)) MiB (start $((rss0/1024))); cgroup memory.peak $((peak/1048576)) MiB; oom_kill=${oom:-?}"
(( peak > 0 && peak <= 256*1048576 )) && [[ "$oom" == 0 ]] && rec PASS 12d "API handles exact-cap deliveries inside 256 MB" "peak $((peak/1048576)) MiB, no OOM kill, $CAP_RUNS deliveries" || rec FAIL 12d "API inside 256 MB" "peak $((peak/1048576)) MiB oom=$oom"
# exact-cap rows are stored and indexed
ncap="$(q "select count(*) from public.seosmith_audits where website_id='${SITE_ID[cap]}' and octet_length(raw_report_json)=$CAP_BYTES")"; nidx="$(q "select count(*) from public.seosmith_lifecycle_indexed i join public.seosmith_audits a using(delivery_id) where a.website_id='${SITE_ID[cap]}' and octet_length(a.raw_report_json)=$CAP_BYTES and i.state='indexed_v1'")"
[[ "$ncap" == "$CAP_RUNS" && "$nidx" == "$CAP_RUNS" ]] && rec PASS 12e "exact-cap rows stored and lifecycle indexed" "$ncap rows, $nidx indexed_v1" || rec FAIL 12e "exact-cap rows stored and indexed" "rows=$ncap indexed=$nidx"

fi   # ONLY_B2
# ---------------------------------------------------------------------------------------------------
echo "== B2: worst-case-escaping exact-cap report: commit body, peak memory, upload time against the timeouts"
# Worst case = the report whose JSON-in-JSON envelope is largest while the report stays exactly HTP_MAX_REPORT_BYTES and admissible.
# Escaping is at most 2x per report byte (a `"` or `\\` becomes 2 bytes in the report and 4 in the envelope; a control character is already
# `\\u0001`, 6 bytes, and becomes 7), so the envelope cannot exceed ~2 x 4,952,756 = 9.9 MB. The 29.7 MB in the H3 comment (6x) is not reachable:
# a raw control byte cannot appear inside the stored report. Pads of `"` (also `\\`, tried in the dev run) reach 1.894x.
WCF="$WORK/wc-quote.json"
"$WCBIN" "$WCF" quote "$CAP_BYTES" 2>"$WORK/wc.err" || { cat "$WORK/wc.err"; rec FAIL 12w "generate worst-case report through generate_wire_v1" "wc_report failed"; }
[[ "$(stat -c %s "$WCF")" == "$CAP_BYTES" ]] || rec FAIL 12w "worst-case report is exactly the cap" "$(stat -c %s "$WCF")"
"$ADMIT" "$WCF" >"$WORK/wc.sum" 2>"$WORK/wc.admit.err" || { cat "$WORK/wc.admit.err"; rec FAIL 12w "worst-case report admissible (receiver admit)" "admit failed"; }
wc_esc="$(tr -cd '\\\\' <"$WCF" | wc -c)"
node "$here/prep.mjs" "$WCF" "$WORK/wc-probe.json" --request "$(uuid)"
wc_probe="$(node "$here/send.mjs" "http://127.0.0.1:1/none" x "$WORK/wc-probe.json" --timeout 500)"; wc_env="$(jq -r .body_bytes <<<"$wc_probe")"
node "$here/prep.mjs" "$CAPF" "$WORK/x-probe.json" --request "$(uuid)"
x_env="$(jq -r .body_bytes <<<"$(node "$here/send.mjs" "http://127.0.0.1:1/none" x "$WORK/x-probe.json" --timeout 500)")"
(( wc_env > CAP_BYTES * 18 / 10 && wc_env <= CAP_BYTES * 2 + 4096 && x_env < CAP_BYTES * 11 / 10 )) \
  && rec PASS 12w "worst-case exact-cap report built by generate_wire_v1: $CAP_BYTES B, schema 4, admitted by the receiver; envelope $wc_env B (x$(echo "scale=3; $wc_env/$CAP_BYTES" | bc)) vs S2's exact-cap fixture envelope $x_env B (x$(echo "scale=3; $x_env/$CAP_BYTES" | bc))" "pad character = double quote (2 bytes in the report, 4 in the envelope); backslashes in the report: $wc_esc; admit summary $(wc -c <"$WORK/wc.sum") B" \
  || rec FAIL 12w "worst-case envelope shape" "report=$CAP_BYTES wc_envelope=$wc_env x_envelope=$x_env"
jq -e '.schema_version==4' "$WCF" >/dev/null || rec FAIL 12w "worst-case report is schema 4" "$(jq .schema_version "$WCF")"

# A second API instance in its own 256 MB / 1 CPU scope (clean memory.peak). Its Supabase traffic goes through the counting forwarder.
cgof() { echo "/sys/fs/cgroup/user.slice/user-$(id -u).slice/user@$(id -u).service/app.slice/$1.scope"; }
CMLOG="$WORK/commit-proxy.log"; : >"$CMLOG"
node "$here/proxy.mjs" --listen 55391 --to "127.0.0.1:$SB_API" --log "$CMLOG" 2>"$WORK/proxy2.err" & pids+=($!)
WCSCOPE=s4x-apiwc; WCPORT=3919
systemd-run --user --scope --quiet --unit="$WCSCOPE" -p MemoryMax=256M -p MemorySwapMax=0 -p CPUQuota=100% \
  env BIND_ADDR="127.0.0.1:$WCPORT" SUPABASE_URL="http://127.0.0.1:55391" SUPABASE_PUBLISHABLE_KEY="$PUBLISHABLE_KEY" SUPABASE_SERVICE_ROLE_KEY="$SERVICE_ROLE_KEY" \
      TMPDIR=/var/tmp HTP_S14_ADMISSION=true HTP_ROLLOUT_LIFECYCLE=true HTP_ROLLOUT_REMEDIATION=true "$APIBIN" >"$WORK/apiwc.log" 2>&1 &
pids+=($!)
wait_for 30 curl -sf "http://127.0.0.1:$WCPORT/integrations/seosmith/capabilities" || { cat "$WORK/apiwc.log"; rec FAIL 12w "second API instance up" "no capabilities"; }
WCINGEST="http://127.0.0.1:$WCPORT/integrations/seosmith/policy-audits"
wcpid="$(head -1 "$(cgof $WCSCOPE)/cgroup.procs")"
wc_rss0="$(grep VmHWM /proc/$wcpid/status | awk '{print $2}')"
cmlines() { wc -l <"$CMLOG"; }
# (a) unthrottled: five worst-case deliveries; body size and time of the API->Supabase commit come from the forwarder log
: >"$WORK/wc.times"; wc_bad=0
for i in $(seq 1 5); do
  id="$(uuid)"; node "$here/prep.mjs" "$WCF" "$WORK/wc-$i.json" --request "$id"
  l0="$(cmlines)"; r="$(node "$here/send.mjs" "$WCINGEST" "${SITE_TOKEN[cap]}" "$WORK/wc-$i.json" --timeout 30000)"
  c="$(tail -n +$((l0+1)) "$CMLOG" | jq -c 'select(.path|endswith("/rpc/commit_seosmith_audit_v4"))' | tail -1)"
  [[ "$(jq -r .status <<<"$r")" == 200 && -n "$c" ]] || { echo "$r"; tail -5 "$WORK/apiwc.log"; rec FAIL 12w "worst-case run $i admitted" "$r commit=$c"; }
  echo "$(jq -r .ms <<<"$r") $(jq -r .req_bytes <<<"$c") $(jq -r .total_ms <<<"$c") $(jq -r .status <<<"$c")" >>"$WORK/wc.times"
  rm -f "$WORK/wc-$i.json"
done
w_rt="$(cut -d' ' -f1 "$WORK/wc.times" | sort -n | tail -1)"; w_cb="$(cut -d' ' -f2 "$WORK/wc.times" | sort -n | tail -1)"; w_cmin="$(cut -d' ' -f2 "$WORK/wc.times" | sort -n | head -1)"; w_ct="$(cut -d' ' -f3 "$WORK/wc.times" | sort -n | tail -1)"
rec INFO 12x "worst-case commit path (5 runs, unthrottled)" "client round trip max ${w_rt} ms; API->Supabase commit request body ${w_cmin}..${w_cb} B (envelope $wc_env B, report $CAP_BYTES B); the commit call (upload + RPC) took max ${w_ct} ms through the forwarder; HTTP status of every commit: $(cut -d' ' -f4 "$WORK/wc.times" | sort -u | tr '\n' ' ')"
(( w_rt < 25000 )) && [[ "$(cut -d' ' -f4 "$WORK/wc.times" | sort -u)" == 200 ]] && (( w_cb > CAP_BYTES * 18 / 10 && w_cb < CAP_BYTES * 2 + 8192 )) \
  && rec PASS 12y "worst-case exact-cap: 5/5 admitted, commit body ${w_cb} B (about 1.9x the report), round trip max ${w_rt} ms inside the 25 s outer timeout" "commit call max ${w_ct} ms" \
  || rec FAIL 12y "worst-case exact-cap runs" "rt=$w_rt commit_body=$w_cb statuses=$(cut -d' ' -f4 "$WORK/wc.times" | sort -u | tr '\n' ' ')"
# (b) producer -> API upload: the request body is paced to a fixed rate on its way to the API (a documented throttle, not tc: tc needs root).
#     The server's BODY_DEADLINE is 8 s; the floor is body_bytes/8 s. Producer client timeout: 30 s. REQUEST_BUDGET: 28 s.
sweep() { # sweep <label> <report-file> <MB/s decimal> <expect 200|503>
  local label="$1" f="$2" mbs="$3" want="$4" id r st err up bytes t
  id="$(uuid)"; node "$here/prep.mjs" "$f" "$WORK/sw.json" --request "$id"
  rm -f "$WORK/thr.log"; node "$here/proxy.mjs" --listen 3920 --to "127.0.0.1:$WCPORT" --rate "$(echo "$mbs*1000000/1" | bc)" --log "$WORK/thr.log" 2>/dev/null & local tp=$!
  wait_for 10 bash -c 'exec 3<>/dev/tcp/127.0.0.1/3920'
  r="$(node "$here/send.mjs" "http://127.0.0.1:3920/integrations/seosmith/policy-audits" "${SITE_TOKEN[cap]}" "$WORK/sw.json" --timeout 30000)"
  sleep 0.3; kill $tp 2>/dev/null; wait $tp 2>/dev/null
  st="$(jq -r .status <<<"$r")"; err="$(jq -r '.body|fromjson? // {}|.error // ""' <<<"$r")"; bytes="$(jq -r .body_bytes <<<"$r")"; t="$(jq -r .ms <<<"$r")"
  up="$(jq -r '.up_ms' "$WORK/thr.log" 2>/dev/null | tail -1)"
  echo "$label ${mbs}MB/s body=${bytes}B status=$st${err:+/$err} total=${t}ms body_upload_seen_by_api=${up:-?}ms (needs $(echo "scale=1; $bytes/($mbs*1000000)" | bc)s at this rate; deadline 8 s)"
  [[ "$st" == "$want" ]]
}
SW="$WORK/sweep.txt"; : >"$SW"; swfail=""
for spec in "worst 0.5 503" "worst 1.0 503" "worst 1.5 200" "worst 2.0 200" "worst 4.0 200" "capx 0.5 503" "capx 0.75 200" "capx 1.5 200"; do
  set -- $spec; f="$WCF"; [[ "$1" == capx ]] && f="$CAPF"
  sweep "$1" "$f" "$2" "$3" >>"$SW" || swfail+=" [$1 $2MB/s want $3]"
done
# the borderline rate is recorded, not asserted: worst-case needs 9.38 MB / 8 s = 1.17 MB/s before any overhead
sweep worst "$WCF" 1.3 200 >>"$SW" || true
cat "$SW"
rec INFO 12z "producer->API upload sweep (rate-limited request body; 8 s body deadline, 28 s request budget, 30 s producer timeout)" "$(tr '\n' ';' <"$SW" | cut -c1-1500)"
[[ -z "$swfail" ]] && rec PASS 12z2 "body deadline behaves as designed: worst-case envelope ($wc_env B) is admitted at >=1.5 MB/s and answered 503 body_timeout at <=1.0 MB/s; S2's exact-cap envelope ($x_env B) at >=0.75 MB/s and 503 at 0.5 MB/s" "floors: worst-case $(echo "scale=2; $wc_env/8000000" | bc) MB/s ($(echo "scale=1; $wc_env*8/8000000" | bc) Mbit/s), exact-cap fixture $(echo "scale=2; $x_env/8000000" | bc) MB/s ($(echo "scale=1; $x_env*8/8000000" | bc) Mbit/s)" \
  || rec FAIL 12z2 "body deadline behaviour" "unexpected:$swfail :: $(tr '\n' ';' <"$SW" | cut -c1-600)"
nbt="$(grep -c 'status=503/body_timeout' "$SW")"; (( nbt >= 3 )) || rec FAIL 12z2 "503 body_timeout seen on the slow rates" "count=$nbt"
# (c) memory over everything this instance did: 5 unthrottled + throttled worst-case and exact-cap uploads
wc_rss1="$(grep VmHWM /proc/$wcpid/status | awk '{print $2}')"; wc_peak="$(cat "$(cgof $WCSCOPE)/memory.peak" 2>/dev/null || echo 0)"; wc_oom="$(grep -E '^oom_kill ' "$(cgof $WCSCOPE)/memory.events" 2>/dev/null | cut -d' ' -f2)"
rec INFO 12v "API peak memory with worst-case bodies on the 256 MB scope" "VmHWM $((wc_rss1/1024)) MiB (start $((wc_rss0/1024))); cgroup memory.peak $((wc_peak/1048576)) MiB; oom_kill=${wc_oom:-?}; $(grep -c . "$WORK/wc.times") unthrottled + $(grep -c . "$SW") rate-limited uploads"
(( wc_peak > 0 && wc_peak <= 256*1048576 )) && [[ "$wc_oom" == 0 ]] && rec PASS 12v2 "API inside 256 MB with worst-case bodies (peak $((wc_peak/1048576)) MiB, no OOM kill)" "VmHWM $((wc_rss1/1024)) MiB" || rec FAIL 12v2 "API inside 256 MB with worst-case bodies" "peak $((wc_peak/1048576)) MiB oom=$wc_oom"
systemctl --user stop "$WCSCOPE.scope" >/dev/null 2>&1 || true
if [[ -n "${ONLY_B2:-}" ]]; then report; echo "== ONLY_B2 done; results in $out/results.md"; exit 0; fi

# ---------------------------------------------------------------------------------------------------
echo "== N-M3: commit_seosmith_audit_v4 at --cpus 0.2 on S2's exact-cap fixture, insert timed separately"
"$here/nm3.sh" "$DB" "$CAPF" "$WORK" "$RUNS" "$here" >"$WORK/nm3.out" 2>&1; nrc=$?
cat "$WORK/nm3.out"
rec INFO 13 "N-M3 stages (S2 exact-cap fixture)" "$(tail -12 "$WORK/nm3.out" | tr '\n' ';' | cut -c1-900)"
[[ $nrc == 0 ]] && rec PASS 13a "N-M3 commit <= 10 s at 0.2 CPU / 1 GB, S2 exact-cap fixture ($RUNS runs; p99 = max)" "$(grep -E '^COMMIT' "$WORK/nm3.out" | head -1)" || rec FAIL 13a "N-M3 commit <= 10 s at 0.2 CPU, S2 exact-cap" "$(grep -E '^COMMIT|throttl' "$WORK/nm3.out" | head -3 | tr '\n' ' ')"
# the same gate on the worst-case-escaping report (its jsonb parse, equality re-parse and escapes are the heaviest the cap allows)
"$here/nm3.sh" "$DB" "$WCF" "$WORK" "$RUNS" "$here" 61440 >"$WORK/nm3w.out" 2>&1; nrcw=$?
cat "$WORK/nm3w.out"
rec INFO 13w "N-M3 stages (worst-case-escaping exact-cap report)" "$(tail -12 "$WORK/nm3w.out" | tr '\n' ';' | cut -c1-900)"
[[ $nrcw == 0 ]] && rec PASS 13b "N-M3 commit <= 10 s at 0.2 CPU / 1 GB, worst-case-escaping exact-cap report ($RUNS runs; p99 = max)" "$(grep -E '^COMMIT' "$WORK/nm3w.out" | head -1)" || rec FAIL 13b "N-M3 commit <= 10 s at 0.2 CPU, worst-case report" "$(grep -E '^COMMIT|throttl' "$WORK/nm3w.out" | head -3 | tr '\n' ' ')"

# ---------------------------------------------------------------------------------------------------
echo "== M9: receiver resource gate on a 256 MB cgroup"
mk="$WORK/m9.sh"; cat >"$mk" <<EOF
#!/usr/bin/env bash
"$RCHECK" derive "$CAPF" >"$WORK/m9d.out" 2>&1; drc=\$?
s=\$(date +%s.%N); "$RCHECK" admit "$CAPF" >"$WORK/m9.out" 2>&1; rc=\$?; e=\$(date +%s.%N)
cg=/sys/fs/cgroup\$(cut -d: -f3 /proc/self/cgroup)
echo "rc=\$rc derive_rc=\$drc secs=\$(echo "\$e - \$s" | bc -l) peak=\$(cat \$cg/memory.peak) max=\$(cat \$cg/memory.max)" >"$WORK/m9.res"
EOF
chmod +x "$mk"; systemd-run --user --scope --quiet -p MemoryMax=256M -p MemorySwapMax=0 -p CPUQuota=100% "$mk"
res="$(cat "$WORK/m9.res")"; m9secs="$(sed 's/.*secs=\([0-9.]*\).*/\1/' <<<"$res")"; m9peak="$(sed 's/.*peak=\([0-9]*\).*/\1/' <<<"$res")"
rec INFO 13m9 "M9 resource_check admit exact-cap" "$res :: $(tr '\n' ' ' <"$WORK/m9.out" | cut -c1-300)"
(( m9peak <= 150*1048576 )) && (( $(echo "$m9secs <= 15" | bc -l) )) && grep -q 'rc=0 derive_rc=0' <<<"$res" && rec PASS 13m9 "M9: resource_check derive (the plan's mode) and admit both rc 0; peak <= 150 MiB and within 15 s on a 256 MB cgroup" "peak $((m9peak/1048576)) MiB, ${m9secs} s" || rec FAIL 13m9 "M9 gate" "$res"

# ---------------------------------------------------------------------------------------------------
if [[ "$SKIP_BOUNDS" == 1 ]]; then rec INFO 14 "Q2-bound crawl" "skipped (--skip-crawl-bounds)"; else
echo "== step 13: M8 + N-M4 on the real site (serve mode): the plan's Q2 bounds, then what a crawl can actually achieve"
# Findings that shape this step (review M1): (1) pages[] holds pages AND resources, so max_pages=100 / max_resources=200 bounds 57+200, not 100;
# (2) the evidence contract keeps at most 128 observations (capabilities max_evidence_observations), one per page or resource, so any crawl of this
# site that reaches more than 128 entries is `truncated=true` (H15: such a job is held index_pending and never alerts); (3) with external links on, an
# external origin whose robots.txt answers a redirect/5xx stops the whole crawl as `partial`/`robots_unavailable` (crawler.rs:309-317). A run is
# only "complete" (frontier_exhausted) when the site's resources fit max_resources, so the cases below separate those effects.
bounds_case() { # bounds_case <tag> <max_pages> <max_resources> <ext true|false> <delay_ms>  -> BC_* variables, report in $WORK/rb-<tag>.json
  local tag="$1" mp="$2" mr="$3" ext="$4" dl="$5" RB resp v f
  RB="$(uuid)"; resp="$(submit "$RB" "$KH" 1 https://www.kerryhatcher.com/ "$mp" "$mr" "$ext" "$dl")"; [[ "$(tail -1 <<<"$resp")" == 202 ]] || rec FAIL 14 "submit $tag" "$resp"
  v="$(wait_state "$RB" '.state=="failed" or .delivery_state=="delivered" or .delivery_state=="rejected"' 3000)" || { echo "$v"; rec FAIL 14 "$tag finishes" "timeout: $v"; }
  [[ "$(jq -r .delivery_state <<<"$v")" == delivered ]] || rec FAIL 14 "$tag delivered" "$(jq -c . <<<"$v")"
  f="$WORK/rb-$tag.json"; curl -s "$SEOURL/v1/runs/$RB/report" -H "authorization: Bearer $SEO_API_TOKEN" >"$f"
  BC_id="$RB"; BC_bytes="$(wc -c <"$f")"; BC_db="$(q "select octet_length(raw_report_json) from public.seosmith_audits where delivery_id='$RB'")"
  BC_np="$(jq '[.pages[]|select(.is_resource|not)]|length' "$f")"; BC_nr="$(jq '[.pages[]|select(.is_resource)]|length' "$f")"
  BC_eval="$(jq '.evidence_contract.evaluations|length' "$f")"; BC_trunc="$(jq '.evidence_contract.truncated' "$f")"
  BC_obs="$(jq '.evidence_contract.observations|length' "$f")"; BC_omit="$(jq '.evidence_contract.omitted_observations' "$f")"
  BC_out="$(jq -r .outcome "$f")"; BC_stop="$(jq -r .stop_reason "$f")"; BC_find="$(jq '.findings|length' "$f")"
  BC_detail="max_pages=$mp max_resources=$mr external_links=$ext pages(non-resource)=$BC_np resources=$BC_nr; outcome=$BC_out stop_reason=$BC_stop; report bytes=$BC_bytes (db octet_length=$BC_db, ${BC_bytes}/3962204 of the 80% budget); evaluations=$BC_eval truncated=$BC_trunc observations=$BC_obs omitted=$BC_omit findings=$BC_find; evidence_contract=$(jq -c .evidence_contract "$f" | wc -c)B policy_guidance=$(jq -c .policy_guidance "$f" | wc -c)B finding_coverage=$(jq -c .finding_coverage "$f" | wc -c)B"
  [[ "$BC_db" == "$BC_bytes" ]] || rec FAIL 14 "$tag stored bytes equal the producer's" "db=$BC_db job=$BC_bytes"
}
# 14a: the Q2 bounds exactly as the plan states them (external links on)
bounds_case q2plan 100 200 true 500
robots_culprits() { # external origins whose /robots.txt the crawler would treat as unavailable (not 200/404/410/401/403; redirects are not followed)
  jq -r '[.pages[]|(.links // [])[]|(.url // .)|tostring|capture("^(?<o>https?://[^/]+)")?|.o]|unique[]' "$1" | grep -v '^https://www.kerryhatcher.com$' | while read -r o; do
    c="$(curl -s -m 10 -o /dev/null -w '%{http_code}' "$o/robots.txt")"; case "$c" in 200|404|410|401|403) ;; *) printf '%s=%s ' "$o" "$c";; esac; done; }
cul="$(robots_culprits "$WORK/rb-q2plan.json")"
rec INFO 14a "Q2 bounds as written (100 pages / 200 resources / external links on)" "$BC_detail; external origins whose robots.txt is a redirect/5xx (each stops a crawl that reaches it): ${cul:-none seen now}"
[[ "$BC_out" == complete ]] && q2c=complete || q2c="NOT complete ($BC_stop)"
# 14b: external links off, same bounds: the resource limit, not robots, is what stops it
bounds_case q2off 100 200 false 500
rec INFO 14b "Q2 bounds with external links off" "$BC_detail"
q2off_np="$BC_np"; q2off_nr="$BC_nr"; q2off_trunc="$BC_trunc"
# 14c: a configuration whose evidence is NOT truncated: pages + resources <= 128 observations (external links off)
mr3=$(( 120 - q2off_np )); (( mr3 > 5 )) || mr3=5
bounds_case untrunc 100 "$mr3" false 500
(( BC_bytes <= 3962204 && BC_eval <= 460 && BC_np <= 100 && BC_nr <= mr3 )) && [[ "$BC_trunc" == false && "$BC_obs" -le 128 && "$BC_out" != failed ]] \
  && rec PASS 14c "M8/N-M4 on the real site, untruncated configuration: size <= 80% of the cap, evaluations <= 460, truncated=false, pages <= max_pages, resources <= max_resources" "$BC_detail" \
  || rec FAIL 14c "M8/N-M4 untruncated configuration" "$BC_detail"
# 14d: a COMPLETE crawl (frontier exhausted, robots available, within max_pages): resources raised until the site fits
bounds_case complete 100 3000 false 500
(( BC_bytes <= 3962204 && BC_eval <= 512 && BC_np <= 100 && BC_nr <= 3000 )) && [[ "$BC_out" == complete && "$BC_stop" == frontier_exhausted ]] \
  && rec PASS 14d "M8/N-M4 on a COMPLETE crawl (outcome complete, frontier_exhausted, robots available, pages <= max_pages 100): size <= 80% of the cap, evaluations <= 512" "$BC_detail; evaluations<=460: $([[ $BC_eval -le 460 ]] && echo yes || echo NO); truncated=$BC_trunc (a complete crawl of ${BC_np} pages + ${BC_nr} resources exceeds the 128-observation evidence cap, so its alerts are held)" \
  || rec FAIL 14d "M8/N-M4 complete crawl" "$BC_detail"
rec INFO 14e "Q2 summary" "as written (100/200, ext on) the crawl is $q2c; ext off it hits the resource limit with truncated=$q2off_trunc at $q2off_np pages + $q2off_nr resources; untruncated needs pages+resources <= 128 (max_resources $mr3 here); a complete crawl needs max_resources above the site's resource count"

fi

# ---------------------------------------------------------------------------------------------------
echo "== amendment: Q9 purge semantics"
"$here/q9.sh" "$DB" "$WORK" "$here" >"$WORK/q9.out" 2>&1; qrc=$?; cat "$WORK/q9.out"
[[ $qrc == 0 ]] && rec PASS 15 "Q9 purge semantics (delete schema-2 rows + remediation first)" "$(grep -E '^Q9' "$WORK/q9.out" | tr '\n' ';' | cut -c1-600)" || rec FAIL 15 "Q9 purge semantics" "$(tail -5 "$WORK/q9.out" | tr '\n' ' ')"

report
echo "== ALL STEPS PASSED; results in $out/results.md"
